from typing import List

def rescale_to_unit(numbers: List[float]) -> List[float]:
    largest = max(numbers)
    smallest = min(numbers)

    if largest == smallest:
        return [0.0] * len(numbers)

    for i, num in enumerate(numbers):
        numbers[i] = (numbers[i] - smallest) / (largest - smallest)

    return numbers
