from typing import List

def remove_duplicates(numbers: List[int]) -> List[int]:
    """ From a list of integers, remove all elements that occur more than once.
    Keep order of elements left the same as in the input.
    >>> remove_duplicates([1, 2, 3, 2, 4])
    [1, 3, 4]
    """
    seen = set()
    seen_count = {}
    result = []

    for num in numbers:
        if num not in seen:
            seen.add(num)
            seen_count[num] = 1
        else:
            if seen_count[num] == 1:
                seen_count[num] += 1
                continue
            else:
                del seen_count[num]

    for num in numbers:
        if num in seen:
            result.append(num)

    return result

# Test cases
