import math

def is_multiply_prime(a):
    """Write a function that returns true if the given number is the multiplication of 3 prime numbers
    and false otherwise.
    Knowing that (a) is less then 100. 
    Example:
    is_multiply_prime(30) == True
    30 = 2 * 3 * 5
    """
    def is_prime(n):
        """Check if a number is prime."""
        if n <= 1:
            return False
        if n <= 3:
            return True
        if n % 2 == 0 or n % 3 == 0:
            return False
        i = 5
        while (i * i <= n):
            if n % i == 0 or n % (i + 2) == 0:
                return False
            i += 6
        return True

    if a < 2:
        return False
    if a < 2:
        return False

    primes = []
    for i in range(2, a):
        if is_prime(i):
            primes.append(i)

    if len(primes) < 3:
        return False

    prime_factors = set()
    for factor in primes:
        while a % factor == 0:
            prime_factors.add(factor)
            a //= factor

    if len(prime_factors) == 3:
        return True
    return False
