    Splits the string into words and returns them as a list.
    """
    words = []
    current_word = ""
    in_word = False
    for char in s:
        if char in ", ":
            if current_word:
                words.append(current_word)
                in_word = False
                current_word = ""
        else:
            if not in_word and char != ", ":
                current_word += char
                in_word = True
    if current_word:
        words.append(current_word)
    return words
