from typing import List

def move_one_ball(arr: List[int]) -> bool:
    if not arr:
        return True

    n = len(arr)
    i = None

    # Find the last index that is covered
    for i in range(n - 1, -1, -1):
        if arr[i] > arr[i - 1]:
            break

    # If all elements are in non-increasing order, return True
    if i == 0 and all(arr[i] < arr[i + 1]):
        return True

    # If there is no index covered, no right shift operations are required
    if i is None:
        return True

    # Try performing a right shift
    shifted_arr = arr[:]
    for _ in range(len(arr)):
        shifted_arr.append(shifted_arr[0])
        shifted_arr.pop(0)

    # Check if the shifted array is sorted
    for j in range(1, len(arr)):
        if shifted_arr[j] > shifted_arr[j - 1]:
            return False

    return True
