import re

def valid_date(date):
    # Regex pattern to match the format mm-dd-yyyy
    date_pattern = r"^(0[1-9]|1[0-2])-([0-2][0-9]|3[0-1])-\d{4}$"

    # Check if the date matches the pattern
    if not re.match(date_pattern, date):
        return False

    if len(date) != 10:
        return False

    # Split the date into month, day, and year
    month, day, year = map(int, date.split('-'))

    # Check the month, day, and year validity
    if month < 1 or month > 12:
        return False
    if day < 1 or day > 31:
        return False
    if month in [4, 6, 9, 11] and day > 30:
        return False
    if month == 2 and day > 29:
        return False

    return True
