from functools import cmp_to_key
from typing import List, Tuple

def find_max(words: List[str]) -> str:
    def compare_strings(s1: str, s2: str) -> Tuple[int, str]:
        if len(set(s1)) > len(set(s2)):
            return -1, s1
        elif len(set(s1)) < len(set(s2)):
            return 1, s2
        else:
            if s1 < s2:
                return -1, s1
            elif s1 > s2:
                return 1, s2
            else:
                return 0, s1

    words.sort(key=cmp_to_key(compare_strings))
    return words[0]
